<template>
  <div class="page"><header class="page-header"><div><div class="eyebrow">Workspace</div><h1 class="page-title">Settings</h1><p class="page-subtitle">Tune TaskFlow to the way you work.</p></div></header><div class="settings-stack"><div class="card setting-card"><div class="card-head"><div><h2 class="section-title">Notifications</h2><p class="section-copy">Choose what deserves your attention.</p></div></div><div class="setting-row"><div><strong>Email notifications</strong><p>Receive important workspace updates by email.</p></div><button class="switch" :class="{on:settings.email}" @click="settings.email=!settings.email"></button></div><div class="setting-row"><div><strong>Task reminders</strong><p>Get a reminder when a task is approaching its due date.</p></div><button class="switch" :class="{on:settings.reminders}" @click="settings.reminders=!settings.reminders"></button></div></div><div class="card setting-card"><div class="card-head"><div><h2 class="section-title">Workspace</h2><p class="section-copy">A few preferences for your local workspace.</p></div></div><div class="setting-row"><div><strong>Compact task rows</strong><p>Show more tasks on screen at once.</p></div><button class="switch" :class="{on:settings.compact}" @click="settings.compact=!settings.compact"></button></div><div class="setting-row"><div><strong>Current account</strong><p>{{email}}</p></div><span class="role-badge employee">{{role}}</span></div></div><div class="card setting-card"><div class="setting-row"><div><strong class="danger">Sign out of TaskFlow</strong><p>This will remove your local session from this browser.</p></div><button class="secondary-button" @click="logout">Sign out</button></div></div></div></div>
</template>
<script setup>
import {reactive} from 'vue';import {useRouter} from 'vue-router';const router=useRouter(),settings=reactive({email:true,reminders:true,compact:false}),email=localStorage.getItem('userEmail')||'Not available',role=localStorage.getItem('role')||'EMPLOYEE';function logout(){['token','role','userId','userName','userEmail','team'].forEach(k=>localStorage.removeItem(k));router.push('/login')}
</script>
